CREATE TABLE rol (nombre VARCHAR(60) PRIMARY KEY, edicion_propia BOOLEAN NOT NULL);
CREATE TABLE rol_privilegio (rol_nombre VARCHAR(60) NOT NULL REFERENCES rol(nombre), privilegio VARCHAR(80) NOT NULL, PRIMARY KEY(rol_nombre, privilegio));
CREATE TABLE usuario (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, usuario VARCHAR(80) NOT NULL UNIQUE, nombre VARCHAR(150) NOT NULL, clave VARCHAR(255) NOT NULL, rol_nombre VARCHAR(60) NOT NULL REFERENCES rol(nombre));
CREATE TABLE lote (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, codigo VARCHAR(30) NOT NULL UNIQUE, nombre VARCHAR(150) NOT NULL, hectareas DOUBLE PRECISION NOT NULL, cultivo VARCHAR(80) NOT NULL, valle VARCHAR(80) NOT NULL, campania_cerrada BOOLEAN NOT NULL, dosis_maxima_por_hectarea DOUBLE PRECISION NOT NULL);
CREATE TABLE labor (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, lote_id BIGINT NOT NULL REFERENCES lote(id), tipo VARCHAR(30) NOT NULL, fecha DATE NOT NULL, autor_id BIGINT NOT NULL REFERENCES usuario(id), cantidad DOUBLE PRECISION NOT NULL, observacion VARCHAR(1000) NOT NULL, registrado_en TIMESTAMP NOT NULL, cliente_id VARCHAR(80), CONSTRAINT uq_labor_cliente UNIQUE(autor_id,cliente_id));
CREATE INDEX idx_labor_lote ON labor(lote_id,fecha);
